export type SurveyStage = "draft" | "review" | "sent";
export interface SurveyAnswers { name: string; region: string; }
export interface SurveySnapshot { stage: SurveyStage; answers: SurveyAnswers; }
export type SurveyListener = (answers: SurveyAnswers) => void;

export class SurveyFlow {
  private stage: SurveyStage = "draft";
  private answers: SurveyAnswers = { name: "", region: "" };
  private readonly listeners = new Set<SurveyListener>();

  setAnswer(field: keyof SurveyAnswers, value: string): void {
    if (this.stage !== "draft") throw new Error("Answers are locked");
    this.answers = { ...this.answers, [field]: value.trim() };
  }

  next(): void {
    if (this.stage === "draft") {
      if (this.answers.name.length === 0 && this.answers.region.length === 0) {
        throw new Error("Incomplete survey");
      }
      this.stage = "review";
    } else if (this.stage === "review") {
      this.stage = "sent";
      for (const listener of this.listeners) listener({ ...this.answers });
    }
  }

  previous(): void {
    if (this.stage === "review") this.stage = "draft";
  }

  reset(): void {
    this.stage = "draft";
    this.answers = { name: "", region: "" };
  }

  subscribe(listener: SurveyListener): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  }

  snapshot(): SurveySnapshot {
    return { stage: this.stage, answers: { ...this.answers } };
  }
}
```

