import { SurveyFlow } from "./solution";
import type { SurveyAnswers, SurveyListener, SurveySnapshot, SurveyStage } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function expectMessage(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof Error, "expected Error");
  if (thrown.message !== message) throw new Error(`expected ${message}, got ${thrown.message}`);
}

const draft: SurveyStage = "draft";
const flow = new SurveyFlow();
let snapshot: SurveySnapshot = flow.snapshot();
if (snapshot.stage !== draft || snapshot.answers.name !== "" || snapshot.answers.region !== "") {
  throw new Error("incorrect initial snapshot");
}
snapshot.answers.name = "external";
if (flow.snapshot().answers.name !== "") throw new Error("snapshot was not defensive");

flow.setAnswer("name", " Ada ");
expectMessage(() => flow.next(), "Incomplete survey");
if (flow.snapshot().stage !== "draft") throw new Error("incomplete next changed stage");
flow.setAnswer("region", "  EU  ");
flow.next();
snapshot = flow.snapshot();
if (snapshot.stage !== "review" || snapshot.answers.name !== "Ada" || snapshot.answers.region !== "EU") {
  throw new Error("answer normalization or draft transition incorrect");
}
expectMessage(() => flow.setAnswer("name", "Grace"), "Answers are locked");
flow.previous();
if (flow.snapshot().stage !== "draft") throw new Error("review previous must return to draft");
flow.previous();
if (flow.snapshot().stage !== "draft") throw new Error("draft previous must be a no-op");

const calls: string[] = [];
const first: SurveyListener = (answers: SurveyAnswers) => {
  calls.push(`first:${answers.name}:${answers.region}`);
  answers.name = "mutated-by-listener";
};
const second: SurveyListener = (answers) => calls.push(`second:${answers.name}:${answers.region}`);
const unsubscribeFirst = flow.subscribe(first);
flow.subscribe(second);
flow.next();
flow.next();
if (calls.join("|") !== "first:Ada:EU|second:Ada:EU") throw new Error("listeners were not ordered or isolated");
if (flow.snapshot().answers.name !== "Ada") throw new Error("listener mutation affected stored state");
flow.next();
if (calls.length !== 2 || flow.snapshot().stage !== "sent") throw new Error("sent next must be a no-op");

unsubscribeFirst();
unsubscribeFirst();
flow.reset();
snapshot = flow.snapshot();
if (snapshot.stage !== "draft" || snapshot.answers.name !== "" || snapshot.answers.region !== "") {
  throw new Error("reset did not clear stage and answers");
}
flow.setAnswer("name", "N");
flow.setAnswer("region", "R");
flow.next();
flow.next();
if (calls.join("|") !== "first:Ada:EU|second:Ada:EU|second:N:R") {
  throw new Error("reset removed listener or unsubscribe was not idempotent");
}

const blank = new SurveyFlow();
blank.setAnswer("name", "  ");
blank.setAnswer("region", "R");
expectMessage(() => blank.next(), "Incomplete survey");

